Author:     John Bieling <john@thunderbird.net>
AuthorDate: Tue Nov 11 19:35:58 2025 +0200
Commit:     John Bieling <john@thunderbird.net>
CommitDate: Tue Nov 11 19:35:58 2025 +0200

    Bug 1988561 - Expose mail.inline_attachments as a read-only property in the messengerSettings API. r=mkmelin


    Helpful information for add-ons which add additional information
    to the message area. For example the Audio Preview add-on can skip
    its modification if the audio file is already visible inline.

    Differential Revision: https://phabricator.services.mozilla.com/D271357

diff --git a/mail/components/extensions/parent/ext-messengerSettings.js b/mail/components/extensions/parent/ext-messengerSettings.js
index e29d89e6b7e..d80248eb283 100644
--- a/mail/components/extensions/parent/ext-messengerSettings.js
+++ b/mail/components/extensions/parent/ext-messengerSettings.js
@@ -29,6 +29,14 @@ ExtensionPreferencesManager.addSetting("messageLineLengthLimit", {
   },
 });

+ExtensionPreferencesManager.addSetting("readerDisplayAttachmentsInline", {
+  permission: "messengerSettings",
+  prefNames: ["mail.inline_attachments"],
+  getCallback() {
+    return Services.prefs.getBoolPref("mail.inline_attachments");
+  },
+});
+
 this.messengerSettings = class extends ExtensionAPI {
   getAPI(context) {
     function makeSettingsAPI(options) {
@@ -54,6 +62,10 @@ this.messengerSettings = class extends ExtensionAPI {
           name: "messagePlainTextFlowedOutputEnabled",
           readOnly: true,
         }),
+        readerDisplayAttachmentsInline: makeSettingsAPI({
+          name: "readerDisplayAttachmentsInline",
+          readOnly: true,
+        }),
       },
     };
   }
diff --git a/mail/components/extensions/schemas/messenger_settings.json b/mail/components/extensions/schemas/messenger_settings.json
index 5ac732a34ab..96578c03672 100644
--- a/mail/components/extensions/schemas/messenger_settings.json
+++ b/mail/components/extensions/schemas/messenger_settings.json
@@ -18,13 +18,17 @@
     "description": "The messengerSettings API allows to access global messenger settings.",
     "permissions": ["messengerSettings"],
     "properties": {
+      "messageLineLengthLimit": {
+        "$ref": "types.Setting",
+        "description": "The line length limit for outgoing messages, to comply with requirements from RFC 2822. See description of $(ref:messengerSettings.messagePlainTextFlowedOutputEnabled). This property is read-only."
+      },
       "messagePlainTextFlowedOutputEnabled": {
         "$ref": "types.Setting",
-        "description": "Whether long lines in outgoing plain text messages will get soft line breaks (<var> \n</var>) or hard line breaks (<var>\n</var>), to comply with requirements from RFC 2822. Soft line breaks will be ignored when displayed by the receiving client. When flowed output is enabled, add-ons should not create plain text messages with manually inserted hard or soft line breaks to achieve a certain text width, as that will most probably interfere with the default line break handling and generate ridged text. When flowed output is disabled, add-ons could add hard line breaks to have control over the final message, but any line longer than the maximum line length will still receive additional hard line breaks. See $(ref:messengerSettings.messageLineLengthLimit)."
+        "description": "Whether long lines in outgoing plain text messages will get soft line breaks (<var> \n</var>) or hard line breaks (<var>\n</var>), to comply with requirements from RFC 2822. Soft line breaks will be ignored when displayed by the receiving client. When flowed output is enabled, add-ons should not create plain text messages with manually inserted hard or soft line breaks to achieve a certain text width, as that will most probably interfere with the default line break handling and generate ridged text. When flowed output is disabled, add-ons could add hard line breaks to have control over the final message, but any line longer than the maximum line length will still receive additional hard line breaks. See $(ref:messengerSettings.messageLineLengthLimit). This property is read-only."
       },
-      "messageLineLengthLimit": {
+      "readerDisplayAttachmentsInline": {
         "$ref": "types.Setting",
-        "description": "The line length limit for outgoing messages, to comply with requirements from RFC 2822. See description of $(ref:messengerSettings.messagePlainTextFlowedOutputEnabled)."
+        "description": "Whether supported attachments (for example, media files) are shown inline within the body of displayed messages. This property is read-only."
       }
     }
   }
